(()=>{
 const near=document.getElementById('near-toggle'),noise=document.getElementById('loud-toggle'),status=document.getElementById('glasses-status'),stage=document.querySelector('.cat-stage'),cat=stage.querySelector('.cat-visitor');
 let x=77,phase='ready',deadline=0,noisyUntil=0,dragging=false,offset=0,audio;
 cat.tabIndex=0;cat.setAttribute('role','slider');cat.setAttribute('aria-label','Other cat distance. Drag or use left and right arrow keys.');cat.setAttribute('aria-valuemin','39');cat.setAttribute('aria-valuemax','77');
 function meow(){try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const t=audio.currentTime,osc=audio.createOscillator(),filter=audio.createBiquadFilter(),gain=audio.createGain();osc.type='sawtooth';osc.frequency.setValueAtTime(540,t);osc.frequency.exponentialRampToValueAtTime(850,t+.13);osc.frequency.exponentialRampToValueAtTime(370,t+.8);filter.type='bandpass';filter.Q.value=2;filter.frequency.setValueAtTime(1700,t);filter.frequency.exponentialRampToValueAtTime(650,t+.85);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.45,t+.05);gain.gain.exponentialRampToValueAtTime(.001,t+.95);osc.connect(filter).connect(gain).connect(audio.destination);osc.start(t);osc.stop(t+1);}catch{}}
 function position(value){x=Math.max(39,Math.min(77,value));cat.style.left=x+'%';cat.setAttribute('aria-valuenow',String(Math.round(x)));cat.setAttribute('aria-valuetext',x<55?'Inside personal space':'Outside personal space');near.setAttribute('aria-pressed',String(x<55));near.textContent=x<55?'Move cat away':'Bring cat closer';stage.style.setProperty('--splash-width',Math.max(16,x-20)+'%');tick();}
 function aim(){const r=stage.getBoundingClientRect(),w=stage.querySelector('.cat-wearer img').getBoundingClientRect(),v=cat.getBoundingClientRect(),svg=stage.querySelector('.cat-splash');svg.setAttribute('viewBox',`0 0 ${r.width} ${r.height}`);const sx=w.right-r.left-12,sy=w.top-r.top+w.height*.42,tx=v.left-r.left+v.width*.5,ty=v.top-r.top+v.height*.35;svg.querySelector('.water-jet').setAttribute('d',`M${sx} ${sy} Q${(sx+tx)/2} ${Math.min(sy,ty)-40} ${tx} ${ty}`);svg.querySelector('.drop-target').setAttribute('transform',`translate(${tx-300} ${ty-95})`);}function tick(){aim();stage.classList.toggle('is-near',x<55);const now=performance.now(),loud=now<noisyUntil;stage.classList.toggle('is-loud',loud);if(phase==='spraying'&&now>=deadline){phase='cooldown';deadline=now+10000;stage.classList.remove('is-splash');}else if(phase==='cooldown'&&now>=deadline){phase='ready';}if(phase==='ready'&&x<55&&loud){phase='spraying';deadline=now+3000;stage.classList.add('is-splash');}stage.dataset.phase=phase;status.textContent=phase==='spraying'?'Splashing · '+Math.ceil((deadline-now)/1000)+'s':phase==='cooldown'?'Cooling down · ready in '+Math.ceil((deadline-now)/1000)+'s':x<55?'Inside the boundary. Press Make noise to meow.':'Drag the cat across the boundary, then make some noise.';}
 noise.removeAttribute('aria-pressed');noise.textContent='Make noise · meow';noise.addEventListener('click',()=>{meow();noisyUntil=performance.now()+1200;tick();});near.addEventListener('click',()=>position(x<55?77:44));
 cat.addEventListener('pointerdown',e=>{if(e.button!==0)return;dragging=true;offset=e.clientX-cat.getBoundingClientRect().left;cat.setPointerCapture(e.pointerId);cat.classList.add('dragging');e.preventDefault();});cat.addEventListener('pointermove',e=>{if(dragging){const box=stage.getBoundingClientRect();position((e.clientX-box.left-offset)/box.width*100);}});function release(){dragging=false;cat.classList.remove('dragging')}cat.addEventListener('pointerup',release);cat.addEventListener('pointercancel',release);cat.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();position(e.key==='Home'?39:e.key==='End'?77:x+(e.key==='ArrowLeft'?-3:3));}});cat.querySelector('img').draggable=false;
 document.getElementById('cat-reset').addEventListener('click',()=>{noisyUntil=0;position(77);});document.addEventListener('visibilitychange',()=>{if(document.hidden)noisyUntil=0;});setInterval(tick,100);position(77);
})();
(()=>{const zones=[['Intimate space','Up to approximately 0.45 m','The closest encounters, usually reserved for people we trust. The same distance can feel comforting or intrusive.'],['Personal space','Approximately 0.45–1.2 m','The space of familiar conversation. Who is approaching matters as much as how close they stand.'],['Social space','Approximately 1.2–3.6 m','A little more distance for less familiar or more formal encounters. Space helps frame the relationship.'],['Public space','Beyond approximately 3.6 m','The distance of addressing a group, where the interaction becomes less personal.']];const buttons=[...document.querySelectorAll('[data-zone]')];function select(i){buttons.forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));document.querySelectorAll('[data-ring]').forEach(r=>r.classList.toggle('is-active',Number(r.dataset.ring)===i));document.getElementById('prox-title').textContent=zones[i][0];document.getElementById('prox-distance').textContent=zones[i][1];document.getElementById('prox-description').textContent=zones[i][2];}buttons.forEach((b,i)=>{b.addEventListener('click',()=>select(i));b.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')select(i)});b.addEventListener('focus',()=>select(i));});select(1);})();
(()=>{const content={distance:['Ultrasonic distance sensor','Measures how close the other person is. Its reading provides the proximity condition for the response.'],sound:['Sound sensor','Measures sound level, without recording or understanding speech. A loud sound supplies the second condition.'],arduino:['Arduino · the decision maker','Checks distance and sound together. In this demonstration, a response lasts 3 seconds, followed by a 10-second cooldown.'],relay:['Relay · the switch','Receives the control signal from Arduino and switches the pump. It connects the decision to the physical response.'],pump:['Pump + tubing','Moves water through the tubing to the nozzle on the glasses, making an invisible boundary visible.']};function choose(key){document.querySelectorAll('[data-component]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.component===key)));document.querySelectorAll('[data-circuit-part]').forEach(g=>g.classList.toggle('selected',g.dataset.circuitPart===key));document.getElementById('as-part-title').textContent=content[key][0];document.getElementById('as-part-description').textContent=content[key][1];}document.querySelectorAll('[data-component]').forEach(b=>{b.addEventListener('click',()=>choose(b.dataset.component));b.addEventListener('focus',()=>choose(b.dataset.component));});document.querySelectorAll('[data-circuit-part]').forEach(g=>{g.addEventListener('click',()=>choose(g.dataset.circuitPart));});choose('distance');})();
